head.script:
scwin.screenId = "jldfil52110";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 15
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 15
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil52110.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_result_oncellclick
 * @author Inswave
 * @date 2026. 09. 15
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        const r = dl && dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.setCorpInfo(r["isurCd"], r["comNm"], r["bzProcsNo"], r["mktNm"], r["typeNm"], r["listTpClssNm"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_window_onclick
 * @author Inswave
 * @date 2026. 09. 15
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_window_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52110.btn_window_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_searchCorpListByBeginIndex
 * @author Inswave
 * @date 2026. 09. 15
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/listInvstg/prtDepocomInfoSearchPop.do?method=searchPreListCorp",
        ref: "dma_searchCorpListByBeginIndexReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil52110.tx_searchCorpListByBeginIndex" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 15
 * @param isurCd comNm bzProcsNo
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = async function (isurCd, comNm, bzProcsNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "bzProcsNo : " + bzProcsNo + "\n";
    const returnKey = '' + $c.data.readValue("dma_pageContext", "returnKey", { silent: true }) + '';
    try {
        (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function () { return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function () { return null; }, scwin: {} }).scwin || {})).setCorpInfo === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function () { return null; }, scwin: {} }).scwin || {})).setCorpInfo(isurCd, comNm, bzProcsNo) : void 0), $c.win.closePopup([isurCd, comNm, bzProcsNo]));
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil52110' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + str);
    }
};


/**
 * @method
 * @name scwin.searchCorpListByBeginIndex
 * @author Inswave
 * @date 2026. 09. 15
 * @param
 * @returns
 * @hidden N
*/
scwin.searchCorpListByBeginIndex = async function () {
    (document.corpListForm || { elements: [] }).action = "/listInvstg/prtDepocomInfoSearchPop.do?method=searchPreListCorp";
    (document.corpListForm || { elements: [] }).target = "iframe";
    await scwin.tx_searchCorpListByBeginIndex();
};
